const p = msg.payload || {};
const required = [
  'event_time','vehicle_id','model','station_code','characteristic_code',
  'shift_code','target_value','lower_spec_limit','upper_spec_limit',
  'measured_value','unit'
];
const missing = required.filter(k => p[k] === undefined || p[k] === null || p[k] === '');
if (missing.length) {
  msg.statusCode = 400;
  msg.payload = {error: 'Missing required fields', fields: missing};
  return [null, msg];
}
if (Number(p.upper_spec_limit) <= Number(p.lower_spec_limit)) {
  msg.statusCode = 400;
  msg.payload = {error: 'upper_spec_limit must be greater than lower_spec_limit'};
  return [null, msg];
}
p.source = p.source || 'node-red';
p.pipeline_received_at = new Date().toISOString();
msg.payload = p;
msg.headers = {'Content-Type': 'application/json'};
return [msg, null];
